"""Chemometric modelling functions for FoodomicsPy.This module currently provides partial least-squares regression withcomponent optimization, cross-validation, calibration statistics,predictions, residuals, and latent-variable outputs."""from __future__ import annotationsfrom typing import Anyimport numpy as npimport pandas as pdfrom sklearn.cross_decomposition import PLSRegressionfrom sklearn.metrics import (    mean_absolute_error,    mean_squared_error,    r2_score,)from sklearn.model_selection import (    GroupKFold,    KFold,)# =============================================================================# PARTIAL LEAST-SQUARES REGRESSION# =============================================================================def perform_pls(    X,    y,    max_components=15,    cv=5,    groups=None,    scale=False,    shuffle=True,    random_state=42,    selection_metric="rmsecv",    selection_rule="minimum",    tolerance=0.01,):    """    Perform partial least-squares regression with cross-validation.    The function:    1. validates X, y, and the cross-validation design,    2. tests different numbers of PLS components,    3. generates cross-validated predictions for every component number,    4. selects the optimal number of components,    5. fits the final PLS model using all samples,    6. calculates calibration and cross-validation statistics,    7. returns predictions, residuals, latent-variable outputs, and       component-optimization results.    Parameters    ----------    X : pandas.DataFrame or array-like of shape (n_samples, n_features)        Predictor matrix.        Rows represent samples and columns represent predictor variables.        Examples include:        - NIR spectra        - FTIR spectra        - NMR spectra        - LF-NMR data        - metabolomics features        - ordinary tabular predictor variables    y : pandas.Series, pandas.DataFrame, or array-like        Continuous response variable.        A pandas DataFrame must contain exactly one column.    max_components : int, default=15        Maximum number of PLS components to test.        The value is automatically reduced when the requested number is        not allowed by the dataset size or cross-validation design.    cv : int, default=5        Number of cross-validation folds.    groups : array-like or None, default=None        Optional group label for every sample.        When supplied, GroupKFold is used and samples belonging to the        same group are always kept in the same fold.        This is strongly recommended when X contains technical        replicates, repeated measurements, measurements from the same        animal/person, or other related observations.    scale : bool, default=False        Whether PLSRegression should internally scale predictor        variables.        Usually set this to False when X has already been appropriately        preprocessed before calling perform_pls().    shuffle : bool, default=True        Whether ordinary K-fold cross-validation should shuffle samples.        Ignored when groups is supplied.    random_state : int or None, default=42        Random seed used for shuffled K-fold cross-validation.    selection_metric : {"rmsecv", "maecv"}, default="rmsecv"        Cross-validation metric used to identify the best model.    selection_rule : {"minimum", "within_tolerance"}, default="minimum"        Rule used to select the number of PLS components.        "minimum"            Selects the component number giving the minimum value of            selection_metric.        "within_tolerance"            Selects the smallest component number whose validation error            is within the specified tolerance of the minimum validation            error.            This can favor a simpler model when several models perform            almost equally well.    tolerance : float, default=0.01        Relative tolerance used when:            selection_rule="within_tolerance"        For example, tolerance=0.01 allows models whose validation error        is within 1% of the minimum.    Returns    -------    dict        Dictionary containing the fitted model, model settings,        validation results, predictions, residuals, statistics,        feature/sample information, cross-validation splits, and PLS        latent-variable outputs.    Notes    -----    Cross-validated predictions are generated manually using the same    cross-validation splits for every tested component number.    This ensures that model comparison is based on identical folds.    Residuals are defined as:        residual = measured - predicted    Q2CV is calculated as:        Q2CV = 1 - PRESS / TSS    where:        PRESS = sum((y - y_cv_predicted)^2)        TSS = sum((y - mean(y))^2)    Examples    --------    Basic PLS regression:    >>> result = perform_pls(    ...     X=X,    ...     y=y,    ...     max_components=15,    ...     cv=5,    ... )    Group-aware cross-validation:    >>> result = perform_pls(    ...     X=X,    ...     y=y,    ...     max_components=15,    ...     cv=5,    ...     groups=groups,    ... )    Select a simpler model when performance is within 1% of the optimum:    >>> result = perform_pls(    ...     X=X,    ...     y=y,    ...     selection_rule="within_tolerance",    ...     tolerance=0.01,    ... )    """    # =========================================================================    # 1. VALIDATE GENERAL ARGUMENTS    # =========================================================================    if not isinstance(max_components, int) or max_components < 1:        raise ValueError(            "'max_components' must be a positive integer."        )    if not isinstance(cv, int) or cv < 2:        raise ValueError(            "'cv' must be an integer greater than or equal to 2."        )    valid_selection_metrics = {        "rmsecv",        "maecv",    }    if selection_metric not in valid_selection_metrics:        raise ValueError(            "'selection_metric' must be one of: "            f"{sorted(valid_selection_metrics)}."        )    valid_selection_rules = {        "minimum",        "within_tolerance",    }    if selection_rule not in valid_selection_rules:        raise ValueError(            "'selection_rule' must be one of: "            f"{sorted(valid_selection_rules)}."        )    if tolerance < 0:        raise ValueError(            "'tolerance' must be greater than or equal to 0."        )    # =========================================================================    # 2. PREPARE X    # =========================================================================    if isinstance(X, pd.DataFrame):        sample_names = X.index.to_numpy(copy=True)        feature_names = X.columns.to_numpy(copy=True)        X_array = X.to_numpy(            dtype=float,            copy=True,        )    else:        X_array = np.asarray(            X,            dtype=float,        )        if X_array.ndim != 2:            raise ValueError(                "'X' must be a two-dimensional matrix with shape "                "(n_samples, n_features)."            )        sample_names = np.arange(            X_array.shape[0]        )        feature_names = np.arange(            X_array.shape[1]        )    # =========================================================================    # 3. PREPARE y    # =========================================================================    if isinstance(y, pd.Series):        y_name = y.name        y_array = y.to_numpy(            dtype=float,            copy=True,        )    elif isinstance(y, pd.DataFrame):        if y.shape[1] != 1:            raise ValueError(                "perform_pls() currently supports one response variable. "                "Supply y as a Series or a DataFrame with one column."            )        y_name = y.columns[0]        y_array = y.iloc[:, 0].to_numpy(            dtype=float,            copy=True,        )    else:        y_name = None        y_array = np.asarray(            y,            dtype=float,        )    y_array = np.squeeze(        y_array    )    if y_array.ndim != 1:        raise ValueError(            "'y' must contain one continuous response variable."        )    # =========================================================================    # 4. VALIDATE DIMENSIONS    # =========================================================================    n_samples, n_features = X_array.shape    if n_samples != len(y_array):        raise ValueError(            "X and y contain different numbers of samples: "            f"X has {n_samples}, while y has {len(y_array)}."        )    if n_samples < 3:        raise ValueError(            "At least three samples are required for PLS regression."        )    if n_features < 1:        raise ValueError(            "X must contain at least one predictor variable."        )    if cv > n_samples:        raise ValueError(            "'cv' cannot exceed the number of samples. "            f"Received cv={cv} and n_samples={n_samples}."        )    # =========================================================================    # 5. VALIDATE VALUES    # =========================================================================    if not np.isfinite(X_array).all():        raise ValueError(            "X contains NaN or infinite values. "            "Remove or impute them before running perform_pls()."        )    if not np.isfinite(y_array).all():        raise ValueError(            "y contains NaN or infinite values. "            "Remove or impute them before running perform_pls()."        )    y_std = np.std(        y_array,        ddof=1,    )    if np.isclose(        y_std,        0,    ):        raise ValueError(            "y has no variation. "            "PLS regression requires a variable response."        )    # =========================================================================    # 6. PREPARE GROUPS    # =========================================================================    if groups is None:        groups_array = None    else:        groups_array = np.asarray(            groups        )        if groups_array.ndim != 1:            groups_array = np.squeeze(                groups_array            )        if groups_array.ndim != 1:            raise ValueError(                "'groups' must be one-dimensional."            )        if len(groups_array) != n_samples:            raise ValueError(                "'groups' must contain one group label per sample."            )        n_unique_groups = np.unique(            groups_array        ).size        if n_unique_groups < 2:            raise ValueError(                "'groups' must contain at least two unique groups."            )        if cv > n_unique_groups:            raise ValueError(                "'cv' cannot exceed the number of unique groups. "                f"Received cv={cv} and "                f"{n_unique_groups} unique groups."            )    # =========================================================================    # 7. CONSTRUCT CROSS-VALIDATION SPLITS    # =========================================================================    if groups_array is None:        cv_object = KFold(            n_splits=cv,            shuffle=shuffle,            random_state=(                random_state                if shuffle                else None            ),        )        cv_splits = list(            cv_object.split(                X_array,                y_array,            )        )        cv_method = "KFold"    else:        cv_object = GroupKFold(            n_splits=cv        )        cv_splits = list(            cv_object.split(                X_array,                y_array,                groups=groups_array,            )        )        cv_method = "GroupKFold"    # =========================================================================    # 8. DETERMINE MAXIMUM VALID NUMBER OF COMPONENTS    # =========================================================================    minimum_training_size = min(        len(train_index)        for train_index, _ in cv_splits    )    maximum_valid_components = min(        max_components,        n_features,        minimum_training_size - 1,    )    if maximum_valid_components < 1:        raise ValueError(            "The dataset and cross-validation design do not allow "            "even one PLS component."        )    if maximum_valid_components < max_components:        print(            "Warning: max_components was reduced from "            f"{max_components} to {maximum_valid_components} "            "because of the dataset size or CV design."        )    # =========================================================================    # 9. TEST NUMBER OF COMPONENTS    # =========================================================================    component_records = []    predictions_by_component = {}    for n_components in range(        1,        maximum_valid_components + 1,    ):        # ---------------------------------------------------------------------        # Storage for out-of-fold predictions        # ---------------------------------------------------------------------        y_cv_predicted = np.full(            shape=n_samples,            fill_value=np.nan,            dtype=float,        )        # ---------------------------------------------------------------------        # Cross-validation        # ---------------------------------------------------------------------        for train_index, validation_index in cv_splits:            X_train = X_array[                train_index            ]            X_validation = X_array[                validation_index            ]            y_train = y_array[                train_index            ]            model = PLSRegression(                n_components=n_components,                scale=scale,            )            model.fit(                X_train,                y_train,            )            prediction = model.predict(                X_validation            ).reshape(-1)            y_cv_predicted[                validation_index            ] = prediction        # ---------------------------------------------------------------------        # Safety check        # ---------------------------------------------------------------------        if np.isnan(            y_cv_predicted        ).any():            raise RuntimeError(                "Some samples did not receive a cross-validated prediction."            )        # ---------------------------------------------------------------------        # Residuals        # ---------------------------------------------------------------------        residuals_cv = (            y_array            - y_cv_predicted        )        # ---------------------------------------------------------------------        # Metrics        # ---------------------------------------------------------------------        rmsecv = np.sqrt(            mean_squared_error(                y_array,                y_cv_predicted,            )        )        maecv = mean_absolute_error(            y_array,            y_cv_predicted,        )        r2cv = r2_score(            y_array,            y_cv_predicted,        )        bias_cv = np.mean(            residuals_cv        )        press = np.sum(            residuals_cv ** 2        )        tss = np.sum(            (                y_array                - np.mean(y_array)            ) ** 2        )        q2cv = (            1            - press / tss        )        component_records.append(            {                "n_components": n_components,                "rmsecv": rmsecv,                "maecv": maecv,                "r2cv": r2cv,                "q2cv": q2cv,                "bias_cv": bias_cv,            }        )        predictions_by_component[            n_components        ] = y_cv_predicted.copy()    # =========================================================================    # 10. COMPONENT RESULTS TABLE    # =========================================================================    component_results = pd.DataFrame(        component_records    )    # =========================================================================    # 11. SELECT OPTIMAL NUMBER OF COMPONENTS    # =========================================================================    minimum_metric_value = component_results[        selection_metric    ].min()    if selection_rule == "minimum":        best_row_index = component_results[            selection_metric        ].idxmin()    elif selection_rule == "within_tolerance":        threshold = (            minimum_metric_value            * (1 + tolerance)        )        candidate_rows = component_results[            component_results[                selection_metric            ] <= threshold        ]        # Smallest number of components meeting the criterion        best_row_index = candidate_rows[            "n_components"        ].idxmin()    best_n_components = int(        component_results.loc[            best_row_index,            "n_components",        ]    )    # =========================================================================    # 12. RETRIEVE CV PREDICTIONS FOR SELECTED MODEL    # =========================================================================    y_cv_predicted = predictions_by_component[        best_n_components    ]    residuals_cv = (        y_array        - y_cv_predicted    )    # =========================================================================    # 13. FIT FINAL MODEL USING ALL SAMPLES    # =========================================================================    final_model = PLSRegression(        n_components=best_n_components,        scale=scale,    )    final_model.fit(        X_array,        y_array,    )    # =========================================================================    # 14. CALIBRATION PREDICTIONS    # =========================================================================    y_calibration_predicted = (        final_model.predict(            X_array        ).reshape(-1)    )    residuals_calibration = (        y_array        - y_calibration_predicted    )    # =========================================================================    # 15. CROSS-VALIDATION METRICS    # =========================================================================    rmsecv = np.sqrt(        mean_squared_error(            y_array,            y_cv_predicted,        )    )    maecv = mean_absolute_error(        y_array,        y_cv_predicted,    )    r2cv = r2_score(        y_array,        y_cv_predicted,    )    bias_cv = np.mean(        residuals_cv    )    press = np.sum(        residuals_cv ** 2    )    tss = np.sum(        (            y_array            - np.mean(y_array)        ) ** 2    )    q2cv = (        1        - press / tss    )    # =========================================================================    # 16. CALIBRATION METRICS    # =========================================================================    rmsec = np.sqrt(        mean_squared_error(            y_array,            y_calibration_predicted,        )    )    maec = mean_absolute_error(        y_array,        y_calibration_predicted,    )    r2c = r2_score(        y_array,        y_calibration_predicted,    )    bias_calibration = np.mean(        residuals_calibration    )    # =========================================================================    # 17. RPD    # =========================================================================    rpd_cv = (        y_std        / rmsecv    )    # =========================================================================    # 18. PREDICTION-LINE STATISTICS    # =========================================================================    (        prediction_slope,        prediction_intercept,    ) = np.polyfit(        y_array,        y_cv_predicted,        deg=1,    )    # =========================================================================    # 19. PREDICTION TABLE    # =========================================================================    predictions = pd.DataFrame(        {            "sample": sample_names,            "measured": y_array,            "predicted_cv": y_cv_predicted,            "residual_cv": residuals_cv,            "predicted_calibration": (                y_calibration_predicted            ),            "residual_calibration": (                residuals_calibration            ),        },        index=sample_names,    )    predictions.index.name = "sample"    # =========================================================================    # 20. METRICS TABLE    # =========================================================================    metrics = pd.Series(        {            "n_samples": n_samples,            "n_features": n_features,            "n_components": best_n_components,            "rmsec": rmsec,            "rmsecv": rmsecv,            "maec": maec,            "maecv": maecv,            "r2c": r2c,            "r2cv": r2cv,            "q2cv": q2cv,            "rpd_cv": rpd_cv,            "bias_calibration": (                bias_calibration            ),            "bias_cv": bias_cv,            "prediction_slope": (                prediction_slope            ),            "prediction_intercept": (                prediction_intercept            ),        },        name="PLS_metrics",    )    # =========================================================================    # 21. REGRESSION COEFFICIENTS    # =========================================================================    coefficients = pd.Series(        np.asarray(            final_model.coef_        ).reshape(-1),        index=feature_names,        name="coefficient",    )    # =========================================================================    # 22. LATENT VARIABLE TABLES    # =========================================================================    component_names = [        f"LV{i}"        for i in range(            1,            best_n_components + 1,        )    ]    x_scores = pd.DataFrame(        final_model.x_scores_,        index=sample_names,        columns=component_names,    )    x_scores.index.name = "sample"    x_loadings = pd.DataFrame(        final_model.x_loadings_,        index=feature_names,        columns=component_names,    )    x_loadings.index.name = "feature"    x_weights = pd.DataFrame(        final_model.x_weights_,        index=feature_names,        columns=component_names,    )    x_weights.index.name = "feature"    x_rotations = pd.DataFrame(        final_model.x_rotations_,        index=feature_names,        columns=component_names,    )    x_rotations.index.name = "feature"    # y outputs are normally one-response structures    y_scores = pd.DataFrame(        final_model.y_scores_,        index=sample_names,        columns=component_names,    )    y_scores.index.name = "sample"    y_loadings = pd.DataFrame(        final_model.y_loadings_,        index=[            y_name            if y_name is not None            else "y"        ],        columns=component_names,    )    y_weights = pd.DataFrame(        final_model.y_weights_,        index=[            y_name            if y_name is not None            else "y"        ],        columns=component_names,    )    # =========================================================================    # 23. RETURN RESULT    # =========================================================================    result: dict[str, Any] = {        # ---------------------------------------------------------------------        # Model        # ---------------------------------------------------------------------        "model": final_model,        # ---------------------------------------------------------------------        # Model settings        # ---------------------------------------------------------------------        "n_components": best_n_components,        "max_components_tested": (            maximum_valid_components        ),        "selection_metric": selection_metric,        "selection_rule": selection_rule,        "tolerance": tolerance,        "scale": scale,        # ---------------------------------------------------------------------        # Input information        # ---------------------------------------------------------------------        "X": X_array,        "y": y_array,        "y_name": y_name,        "sample_names": sample_names,        "feature_names": feature_names,        "groups": groups_array,        # ---------------------------------------------------------------------        # CV information        # ---------------------------------------------------------------------        "cv": cv,        "cv_method": cv_method,        "cv_splits": cv_splits,        # ---------------------------------------------------------------------        # Component optimization        # ---------------------------------------------------------------------        "component_results": (            component_results        ),        # ---------------------------------------------------------------------        # Summary metrics        # ---------------------------------------------------------------------        "metrics": metrics,        # ---------------------------------------------------------------------        # Prediction information        # ---------------------------------------------------------------------        "predictions": predictions,        "y_measured": y_array,        "y_cv_predicted": (            y_cv_predicted        ),        "y_calibration_predicted": (            y_calibration_predicted        ),        # ---------------------------------------------------------------------        # Residuals        # ---------------------------------------------------------------------        "residuals_cv": (            residuals_cv        ),        "residuals_calibration": (            residuals_calibration        ),        # ---------------------------------------------------------------------        # Individual metrics        # Kept for convenient backward compatibility        # ---------------------------------------------------------------------        "rmsec": rmsec,        "rmsecv": rmsecv,        "maec": maec,        "maecv": maecv,        "r2c": r2c,        "r2cv": r2cv,        "q2cv": q2cv,        "rpd_cv": rpd_cv,        "bias_calibration": (            bias_calibration        ),        "bias_cv": bias_cv,        "prediction_slope": (            prediction_slope        ),        "prediction_intercept": (            prediction_intercept        ),        # ---------------------------------------------------------------------        # Latent-variable outputs        # ---------------------------------------------------------------------        "scores": x_scores,        "x_scores": x_scores,        "y_scores": y_scores,        "x_loadings": x_loadings,        "y_loadings": y_loadings,        "x_weights": x_weights,        "y_weights": y_weights,        "x_rotations": x_rotations,        # ---------------------------------------------------------------------        # Regression coefficients        # ---------------------------------------------------------------------        "coefficients": coefficients,    }    return result